/* @lc app=leetcode id=2603 lang=kotlin */ class Solution { fun pl(g: Map<Int, List<Int>>, deg: IntArray, rem: BooleanArray, start: List<Int>, coins: IntArray) = generateSequence(start) { f -> f.flatMap { u -> true.also { rem[u] = true }.let { g[u].orEmpty().filter { v -> !rem[v] && --deg[v] == 1 && coins[v] == 0 } } }.takeIf { it.isNotEmpty() } }.count() fun rd(g: Map<Int, List<Int>>, deg: IntArray, rem: BooleanArray) = deg.indices.filter { !rem[it] && deg[it] == 1 }.let { ls -> ls.forEach { rem[it] = true }.let { ls.forEach { u -> g[u].orEmpty().filter { !rem[it] }.forEach { deg[it]-- } } } } fun collectTheCoins(coins: IntArray, edges: Array<IntArray>): Int = coins.size.let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { g[it].orEmpty().size }.let { deg -> BooleanArray(n).let { rem -> pl(g, deg, rem, (0 until n).filter { deg[it] == 1 && coins[it] == 0 }, coins).let { rd(g, deg, rem).let { rd(g, deg, rem).let { 2 * maxOf(0, rem.count { !it } - 1) } } } } } } } }